+for (const { name, path } of REPRESENTATIVE_PAGES) {
+  test(`search shortcut badge renders styled (padding/size) — ${name}`, async ({
+    page,
+  }) => {
+    // The ⌘K shortcut badge is Search.astro's own scoped `kbd` styling
